/* JackOS 98 "system" pack: JackOS Help, an HTML Help-style viewer (Contents / Index / Search) with far too many topics. */
(function () {
  'use strict';
  const X = window.SysPack; if (!X || X.P['system.help']) return;
  const A = window.Apps;
  const { I, get, put, qs, qsa, on, h, esc, S, toast, msg, open, mini, pick, touch } = X;

  // topics: [id, title, html]. Keep the writing 1999, UK kid, "Mom".
  const T = [];
  const t = (id, title, html, kw) => T.push({ id, title, html, kw: kw || '' });
  const L = (id, text) => `<a href="#" data-t="${id}">${text}</a>`;
  const R = (id, text) => `<a href="#" data-run="${id}">${text}</a>`;
  const NOTE = s => `<div class="sys-h-note"><b>Note</b> ${s}</div>`;
  const TIP = s => `<div class="sys-h-tip"><b>Tip</b> ${s}</div>`;
  const STEPS = a => `<ol>${a.map(s => `<li>${s}</li>`).join('')}</ol>`;

  // ---- Welcome
  t('welcome', 'Welcome to JackOS 98 Help', `<p>JackOS 98 Help is the place to look when something has gone wrong, or when you just want to know what everything does. There are <b>${'%N%'}</b> topics in here. Jack wrote most of them at the weekend.</p><ul><li>Click <b>Contents</b> to browse the books.</li><li>Click <b>Index</b> and type a word to find it.</li><li>Click <b>Search</b> to search all the words in all the topics (some topics are only findable this way).</li></ul>${TIP('Press <b>F1</b> anywhere on the desktop to open Help.')}`, 'help start begin');
  t('whatsnew', "What's new in JackOS 98", `<p>Loads. Here are the big ones:</p><ul><li>${L('taskmgr', 'JackOS Task Manager')}, for seeing what is going on inside the PC.</li><li>${L('devmgr', 'Device Manager')} with real hardware in it.</li><li>${L('printing', 'A printer that works')} (the JackJet 500) replacing the Epson that is out of cyan.</li><li>${L('themes', 'Desktop Themes')}: Space, Blockology, Dinosaurs, a galaxy far away and more.</li><li>${L('activedesk', 'Active Desktop')} and the Channel Bar.</li><li>${L('welcome-tour', 'The Welcome screen')} with the Discover tour.</li><li>${L('update', 'JackOS Update')} for critical updates, including the Y2K patch.</li><li>${L('secrets', 'More secrets')}. Lots more.</li></ul>`, 'new features');
  t('sysreq', 'System requirements', `<p>JackOS 98 needs:</p><table class="sys-kv"><tr><td>Processor</td><td>A 486DX/66 or better. This PC has a Pentium II 350, which is "overkill" (Dad).</td></tr><tr><td>Memory</td><td>16 MB (24 MB recommended). This PC has 64 MB and Jack still wants more.</td></tr><tr><td>Hard disk</td><td>195 MB free. We have 1.21 GB, most of it games.</td></tr><tr><td>Display</td><td>VGA or better. 800 x 600 is best. 1024 x 768 makes everything tiny.</td></tr><tr><td>Mouse</td><td>Yes. With a ball. Clean the ball.</td></tr><tr><td>Modem</td><td>Optional, but then what is the point.</td></tr></table>`, 'requirements hardware minimum');
  t('about-this-pc', 'About this computer', `<p>This is the family PC. It lives in the hall, next to the phone, which is why the Internet stops when Mom picks up.</p><p>Inside it: a Pentium II 350 MHz on an Intel 440BX board, 64 MB of PC100 SDRAM, a 6.4 GB hard disk, a 32x CD-ROM, a 1.44 MB floppy, an ATI Rage Pro graphics card with a 3dfx Voodoo2 next to it, a JackBlaster 16 sound card and a 56K V.90 modem. The monitor is 14 inches and hums. You can see all of this in ${L('devmgr', 'Device Manager')} and ${R('msinfo32', 'System Information')}.</p>`, 'computer specs pentium');

  // ---- Using JackOS
  t('desktop', 'The desktop', `<p>The desktop is the big teal bit. Things on it:</p><ul><li><b>Icons</b>: double-click them to open things.</li><li><b>The taskbar</b> along the bottom, with the ${L('startmenu', 'Start button')}, buttons for every open window, and the ${L('tray', 'system tray')} with the clock.</li><li><b>The Channel Bar</b>, if you have it showing. See ${L('channels', 'Channels')}.</li></ul><p>Right-click the desktop for ${L('newfolder', 'New')}, ${L('arrange', 'Arrange Icons')} and Properties. Drag a box around icons to select lots at once.</p>`, 'teal background wallpaper');
  t('startmenu', 'The Start menu', `<p>Click <b>Start</b> (bottom left). From there:</p><ul><li><b>Programs</b>: everything installed, in folders. Accessories has the useful stuff. Games has the games. System Tools has the nerdy stuff.</li><li><b>Documents</b>: the last few files you opened.</li><li><b>Settings</b>: Control Panel, Printers, Taskbar.</li><li><b>Find</b>: files, people on JackNet, and <b>Secrets</b> (how many you have found).</li><li><b>Help</b>: this.</li><li><b>Run</b>: type a program name. There are ${L('runcmds', 'secret ones')}.</li><li><b>Shut Down</b>: do this properly or ScanDisk runs next time.</li></ul>`, 'start button programs');
  t('windows', 'JackOS: moving, sizing, closing', `<p>Every program lives in a window with a blue bar on top.</p><ul><li><b>Move</b>: drag the blue title bar.</li><li><b>Resize</b>: drag the bottom-right corner (the little grippy lines).</li><li><b>Maximise</b>: the square button, or double-click the title bar.</li><li><b>Minimise</b>: the _ button. It goes to the taskbar. Click its taskbar button to get it back.</li><li><b>Close</b>: the X. Or Alt+F4 in real life.</li></ul><p>Right-click the taskbar for <b>Cascade</b>, <b>Tile</b> and <b>Minimize All JackOS</b>. The Show Desktop button on the Quick Launch bar hides everything in one click.</p>`, 'maximise minimise close move resize');
  t('taskbar', 'The taskbar', `<p>The grey bar along the bottom. Left to right: the Start button, the Quick Launch buttons (JackNet Explorer, JackMail Express, Show Desktop, View Channels), a button for each open window, and the ${L('tray', 'system tray')}.</p><p>Right-click an empty bit for Cascade / Tile / Minimize All / Task Manager / Properties. Right-click a window's button to Restore, Minimize, Maximize or Close it.</p>${NOTE('Auto hide is switched off. The last time it hid, Jack lost the Start button for a weekend.')}`, 'bar bottom');
  t('tray', 'The system tray', `<p>The sunken box next to the clock. In it:</p><ul><li><b>Speaker</b>: click for the volume slider and Mute. Double-click for ${L('volume', 'Volume Control')}.</li><li><b>Two little computers</b>: how many people are on JackNet right now. Click to go to the chat room.</li><li><b>An egg</b>: ${R('grotchi', 'Jackotchi')}, a tiny virtual pet in an egg. Feed him.</li><li><b>Calendar with a clock</b>: ${L('sched', 'Task Scheduler')}. Right-click to pause it.</li><li><b>A printer</b> appears while the ${L('printing', 'JackJet 500')} is printing. If it goes red, something jammed.</li><li><b>Three bars</b>: the ${L('rsrcmtr', 'Resource Meter')}, once you have run it.</li><li><b>The clock</b>: hold the mouse over it for the date. Double-click for Date/Time Properties.</li></ul>`, 'systray notification icons clock speaker');
  t('clock', 'The clock and the date', `<p>The clock shows the real time. The date is always 1999. Hold the pointer over the clock to see which day in 1999 it is.</p><p>Double-click it for <b>Date/Time Properties</b>: a calendar, an analogue clock and a time zone map. You can change the date. The CMOS battery will change it back. See ${L('forever1999', 'Why is it always 1999?')}</p>`, 'time date');
  t('forever1999', 'Why is it always 1999?', `<p>Because it is. The clock in this computer counts up to midnight on 31 December 1999, goes "HAPPY NEW YEAR", gets the Millennium Bug, says 19100 for a bit and then resets to 1 January 1999. Every year. Nobody has fixed it. Jack says it is a feature.</p><p>Things that depend on the date (what's new on the website, the countdowns, the Millennium task) use the 1999 date. See ${L('y2k', 'The Millennium Bug')}.</p>`, 'year 2000 date');
  t('mouse', 'Using the mouse', `<p><b>Click</b> selects. <b>Double-click</b> opens. <b>Right-click</b> gets a menu of things you can do to whatever you clicked on. Nearly everything has one. Try the desktop, the taskbar, the clock and the tray icons.</p><p>If the pointer jumps about, take the ball out of the bottom of the mouse and pick the fluff off the little rollers.</p><p>Mouse with only one button? Click and hold where you would right-click.</p>`, 'click double-click right-click pointer');
  t('keyboard', 'Keyboard shortcuts', `<table class="sys-kv"><tr><td>F1</td><td>This Help</td></tr><tr><td>Ctrl+Alt+Del</td><td>Close Program (twice for a surprise)</td></tr><tr><td>Ctrl+Shift+Esc</td><td>${L('taskmgr', 'JackOS Task Manager')}</td></tr><tr><td>Esc</td><td>Stop loading / close a menu / wake from the screensaver</td></tr><tr><td>F5</td><td>Refresh (JackNet Explorer)</td></tr><tr><td>F11</td><td>Full screen</td></tr><tr><td>Alt+Left / Alt+Right</td><td>Back / Forward</td></tr><tr><td>Ctrl+D</td><td>Add to Favorites</td></tr><tr><td>F2</td><td>Rename a desktop item</td></tr><tr><td>Up Up Down Down Left Right Left Right B A</td><td>Try it.</td></tr></table>`, 'keys hotkeys');
  t('touch', 'Clicking, holding and dragging', `<p>Everything in JackOS 98 works with clicks: click an icon to open it, click and hold for the right-click menu, and drag jackos by their title bars. JackOS never get wider than the screen. On a small screen the desktop icons go along the top instead of down the side.</p>${NOTE('To select lots of icons at once, drag a box around them on the desktop.')}`, 'click hold drag small screen');
  t('runcmds', 'Start > Run commands', `<p>Start > Run opens a box. Type a program name and press Enter. Some that work:</p><p><code>calc notepad mspaint sol freecell regedit msinfo32 defrag scandisk control taskmgr devmgr sysmon sndrec32 sndvol32 cleanmgr msbackup mstask welcome winhelp themes jackjet printers wupdmgr y2kpatch</code></p><p>And some that do other things. Try <code>help</code> in the Run box for a list, or just try words. Lots of words do something. See ${L('secrets', 'Secrets')}.</p>`, 'run dialog commands');
  t('shutdown', 'Shutting down properly', `${STEPS(['Click <b>Start</b>, then <b>Shut Down</b>.', 'Choose Shut down, Restart, Stand by, or Restart in JACK-DOS mode.', 'Click OK. Wait for "It is now safe to turn off your computer". Then press the big button on the front.'])}${NOTE('If you (or Dave) just switch it off at the wall, ScanDisk runs next time it starts and takes ages. This is why ScanDisk runs every morning.')}`, 'turn off power restart');
  t('msdos', 'JACK-DOS mode', `<p>Start > Shut Down > Restart in MS-DOS mode gets you a black screen with <code>C:\\&gt;</code> on it. Type <code>HELP</code>. Type <code>DIR</code>. Type <code>WIN</code> to come back. Don't type <code>FORMAT</code>.</p>`, 'dos prompt command');

  // ---- Programs
  t('taskmgr', 'JackOS Task Manager', `<p>Task Manager shows everything the computer is doing. Open it with <b>Ctrl+Shift+Esc</b>, from the taskbar's right-click menu, or Start > Programs > Accessories > System Tools.</p><ul><li><b>Applications</b>: every open window. Select one and click End Task to close it, or Switch To to bring it to the front.</li><li><b>Processes</b>: the programs behind the scenes (KERNEL32, EXPLORER, SYSTRAY, MSGSRV32...). End Process stops one. Some of them will not stop. One of them should never be stopped.</li><li><b>Performance</b>: live graphs of the CPU and memory. Run a game and watch the CPU go red. Well, green. It is green on black.</li></ul>${NOTE('GUBBINZ.EXE cannot be ended. Jack has tried. Dave has tried. Dad has tried with a hammer (not really).')}`, 'processes cpu end task ctrl shift esc');
  t('devmgr', 'Device Manager', `<p>Device Manager lists every bit of hardware in the computer, sorted into types. Open it from Control Panel > System > Device Manager, or Start > Run > <code>devmgr</code>.</p><p>Click + to open a category. Double-click a device for its Properties: General (is it working?), Driver (what file makes it work) and Resources (${L('irq', 'IRQ')}, DMA and I/O addresses).</p><p>A yellow <b>!</b> means a problem. A red <b>x</b> means disabled. A yellow <b>?</b> on a category means something in there is unhappy. Right now "Other devices" has a Bug Detector with an IRQ conflict, a Hyperdrive Motivator that doesn't work, and a toaster.</p>`, 'hardware devices drivers');
  t('irq', 'Fixing an IRQ conflict', `<p>An IRQ (Interrupt Request) is a little wire each device uses to shout "oi!" at the processor. There are 16 of them (0 to 15) and most are taken. If two devices share one and don't get on, one of them stops working with a Code 12.</p>${STEPS(['Open ' + L('devmgr', 'Device Manager') + ' and find the device with the <b>!</b> and the IRQ problem (the detector one in Other devices).', 'Double-click it, click the <b>Resources</b> tab.', 'Untick <b>Use automatic settings</b>.', 'Click the Interrupt Request line, then <b>Change Setting...</b>', 'Use the arrows until the "Conflict information" box says no devices are conflicting. (IRQ 9 is held for PCI steering, so it can be shared. Hint hint.)', 'Click OK. Click OK again. Do not restart; it just works.'])}`, 'conflict interrupt code 12 resources');
  t('hyperdrive', 'The Hyperdrive Motivator', `<p>It is in Device Manager under Other devices, with a yellow <b>!</b>. Status: not working (Code 10). It will never work. It is always the motivator. Try the Troubleshooter button, and when it asks if you have tried hitting it, tell the truth.</p><p>Nobody knows how it got into the computer. Jack says it "came in a box". The box said "property of a galaxy far away" in felt tip.</p>`, 'star space lightspeed galaxy');
  t('sysmon', 'System Monitor', `<p>System Monitor draws live graphs of things like processor usage, memory, the swapfile, modem bytes, and how many snacks Gubbinz eats per minute. Edit > Add Item to pick what to watch. View > Line / Bar / Numeric to change the style. Start > Run > <code>sysmon</code>.</p>${TIP('Add "Kernel: Processor Usage", then open a game. Then close the game and watch it calm down. Very soothing.')}`, 'graphs performance monitor');
  t('rsrcmtr', 'Resource Meter', `<p>Resource Meter puts three little bars next to the clock: System, User and GDI resources. When they go yellow, close something. When they go red, JackOS will tell you off. When they hit about 12%, things get interesting.</p><p>Start > Programs > Accessories > System Tools > Resource Meter. Right-click the tray icon to Exit.</p>`, 'resources free memory');
  t('sched', 'Scheduled Tasks', `<p>The Task Scheduler runs programs on a timetable: ScanDisk on Sunday nights, Disk Cleanup monthly, feed Gubbinz at 4pm. Open <b>Scheduled Tasks</b> from My Computer, the tray icon (calendar with a clock), or Start > Run > <code>mstask</code>.</p><p>Double-click <b>Add Scheduled Task</b> for the wizard. Right-click a task for Run, Delete and Properties. Advanced > Pause Task Scheduler stops everything for a bit.</p>${NOTE('"Tidy bedroom" has never run. The program could not be found.')}`, 'task scheduler jobs timer');
  t('backup', 'Backup', `<p>Backup copies your files onto floppy disks in case the hard disk dies. A full backup of this PC is about 5,190 MB, which is about <b>3,600 floppy disks</b>, or about 36 hours of swapping disks. We have 3 disks. Backup gets to disk 3 and gives up.</p><p>Start > Programs > Accessories > System Tools > Backup. Or ask for a Zip drive for Christmas.</p>`, 'floppies copy restore');
  t('cleanmgr', 'Disk Cleanup', `<p>Disk Cleanup finds files you don't need (temporary Internet files, the Recycle Bin, old ScanDisk .CHK files) and deletes them. It is honest about how much space you get back (not much). It will not delete Jack's Goldenballs high scores. It has been told.</p><p>Start > Programs > Accessories > System Tools > Disk Cleanup, or the Disk Cleanup button on the C: drive's Properties.</p>${TIP('The progress bar stops at 99% for a while. That is normal. Everything in 1999 stops at 99% for a while.')}`, 'free space delete temp files');
  t('tuneup', 'Maintenance Wizard', `<p>The Maintenance Wizard sets up ScanDisk, Defrag and Disk Cleanup to run at night. The computer is never on at night, so it runs them when you click Finish instead. Express or Custom; Custom lets you tick "Feed Gubbinz".</p>`, 'tune up schedule scandisk defrag');
  t('accwiz', 'Accessibility Wizard', `<p>Makes JackOS easier to see and use: bigger text, a high-contrast colour scheme, a bigger mouse pointer, SoundSentry (flash instead of beep), StickyKeys and MouseKeys. Start > Programs > Accessories > Accessibility > Accessibility Wizard. Run it again to put things back.</p>`, 'big text contrast large pointer');
  t('sndrec', 'Sound Recorder', `<p>Sound Recorder records up to 60 seconds from the microphone (the little plastic one that came with the sound card) and plays it back. Press the red button to record, the black square to stop, the triangle to play. Effects: louder, quieter, faster (chipmunk), slower, echo and <b>Reverse</b>.</p>${NOTE('Recordings stay inside this computer\'s memory and are never sent anywhere. Shut down and they are gone. If there is no microphone, JackOS records a loud shout for you.')}`, 'record microphone wav');
  t('volume', 'Volume Control', `<p>Click the speaker in the tray for a quick slider and Mute. Double-click it, or Start > Run > <code>sndvol32</code>, for the full mixer: Volume Control, Wave, MIDI, CD Audio, Line-In, Microphone, PC Speaker and Gubbinz. Options > Properties chooses which sliders to show.</p>${NOTE('The real volume knob is on the front of the left speaker. The other speaker is behind the desk.')}`, 'sound mute speaker mixer loud');
  t('printing', 'Printing with the JackJet 500', `<p>The JackJet 500 is the new printer (the Epson is out of cyan). Print from JackNet Explorer's File > Print, the Print button, or any program with a Print command. A printer appears in the tray and the <b>JackJet 500</b> window opens showing the queue and the printer itself.</p><ul><li>Watch the page come out. Click a page in the output tray to look at it.</li><li>If it says <b>PAPER JAM</b>, click the scrunched-up page in the printer to pull it out, then click Retry (or GO).</li><li>If it says <b>ADD PAPER</b>, click the paper tray at the back to load 10 sheets. Then Retry.</li><li>If it says <b>MC FEED A4</b> or something else nobody understands, press GO. See ${L('mcfeed', 'What does MC FEED A4 mean?')}</li></ul><p>Printer > Purge Print Documents empties the queue. Printer > Properties has Paper and Graphics tabs. File > Print Test Page prints the test page.</p>`, 'printer print queue jam paper');
  t('mcfeed', 'What does MC FEED A4 mean?', `<p>Nobody knows. The manual is in the loft. Jack's best guess is "Manual Cassette: feed one sheet of A4". Dave says it means the printer is hungry. Press GO and it carries on.</p><p>Other things the JackJet says: TRAY 1 HUNGRY (Dave was right), LOAD A4 PLAIN PRESS GO, ERR 50.2 RESTART, PAPER WAD AT C, HEAD PARK FAIL. All of them mean "press GO".</p>`, 'printer message lcd error');
  t('printers-folder', 'The Printers folder', `<p>Start > Settings > Printers (or My Computer > Printers) shows the installed printers: the JackJet 500 (default, tick), the Epson Stylus Color 440 (offline, out of cyan) and <b>Add Printer</b>, which runs the Add Printer Wizard. The wizard will let you install the JackJet again. It will be the same JackJet.</p>`, 'add printer wizard epson');
  t('update', 'JackOS Update', `<p>Start > JackOS Update connects to JackOS Update, checks your computer and lists the updates you don't have. Tick the ones you want and click Download. They come down at about 28.8 Kbps, because the modem is a 56K that connects at 49K that gets 28.8 when it is raining. If someone picks up the phone, it redials.</p><p>Critical updates: the ${L('y2k', 'Y2K Compliance Patch')}, a JackNet Explorer security fix, the Gubbinz Compatibility Pack and Critical Update Notification (which tells you about critical updates, including itself).</p>`, 'jackos update download patch');
  t('y2k', 'The Millennium Bug (Y2K)', `<p>Old computers store the year as two digits, so at midnight on 31 December 1999 they think it is 1900 (or, if they are very confused, 19100). This is the Millennium Bug. The news is very worried about it. Mom has bought 40 tins of beans.</p><p>The <b>Y2K Compliance Patch</b> (Start > Programs > Accessories > System Tools, or JackOS Update) fixes it. When you install it the clock says 19100 for a moment, to show you what it is saving you from.</p><p>See also ${L('forever1999', 'Why is it always 1999?')} and the Y2K Checker in Program Files.</p>`, 'year 2000 millennium bug patch 19100');
  t('themes', 'Desktop Themes', `<p>Desktop Themes (Start > Programs > Accessories, or Control Panel, or Run > <code>themes</code>) change the whole look at once: wallpaper, window colours, the mouse pointer, the sounds and the icons. Pick a theme from the list, see the preview, click Apply.</p><p>Themes: JackOS Standard, <b>Gorks!</b>, <b>Outer Space</b>, <b>Blockology</b>, <b>Cube Mania</b>, <b>Haunted House</b>, <b>Dinosaurs</b>, <b>Galaxy Far Away</b>, <b>Under the Sea</b>, <b>Millennium</b>, <b>Hot Dog Stand</b> (no) and <b>The Modemtrix</b>.</p>${TIP('Untick "Mouse pointers" if the glowing blade one gets annoying. It gets annoying.')}`, 'wallpaper colours plus cursor');
  t('activedesk', 'Active Desktop', `<p>Active Desktop turns the desktop into a web page. Right-click the desktop > Active Desktop > <b>View As Web Page</b> puts the Desktop News Network ticker on the desktop, with headlines that other visitors have sent in. <b>Show Channel Bar</b> puts the ${L('channels', 'Channel Bar')} up. <b>Update Now</b> synchronises everything (nothing changes).</p>`, 'web page desktop ticker');
  t('channels', 'Channels and the Channel Bar', `<p>Channels are web sites that send themselves to you so you don't have to ask (the Internet in 1999 is very excited about this). The <b>Channel Bar</b> on the desktop lists them: the JackNet Channel Guide, the Desktop News Network, WeatherWatch 2000, The Cheat Channel, Telly Guide 99, Mom's Kitchen, Jack FM, Galaxy Far Away News and Dave TV.</p><p>Click one to open it. Click <b>Subscribe</b> to subscribe (it does nothing, but it feels good). The Desktop News Network lets you send in a headline; everyone on the site sees it on their ticker.</p>`, 'subscribe push channel bar');
  t('welcome-tour', 'The Welcome screen', `<p>"Welcome to JackOS 98" appears the first time the PC starts. It has four buttons: <b>Register Now</b> (the Registration Wizard), <b>Connect to the Internet</b> (the Internet Connection Wizard), <b>Discover JackOS 98</b> (an animated tour), and <b>Maintain Your Computer</b> (the Maintenance Wizard). Untick "Show this screen each time JackOS 98 starts" to stop it. Start > Programs > Accessories > System Tools > Welcome To JackOS brings it back.</p>`, 'register discover tour first time');
  t('tips', 'Tip of the Day', `<p>A little window with a lightbulb that tells you something useful (sometimes) when JackOS starts. Click Next Tip for another. Untick "Show tips at startup" to make it stop. Start > Programs > Accessories > Tip of the Day brings it back.</p>`, 'tip lightbulb startup');
  t('newfolder', 'New folders, text documents and shortcuts', `<p>Right-click an empty bit of the desktop, point to <b>New</b> and choose:</p><ul><li><b>Folder</b>: makes "New Folder" and lets you type a name. It is a real folder in C:\\JACKOS\\Desktop.</li><li><b>Text Document</b>: makes "New Text Document.txt" and opens it in Notepad when you double-click it.</li><li><b>Shortcut</b>: runs the Create Shortcut wizard. Type a Run command (like <code>calc</code>) or Browse for a program.</li></ul><p>Press F2 to rename, Delete to delete, or right-click for Properties. Your new items are remembered next time.</p>`, 'create new folder shortcut desktop');
  t('arrange', 'Arranging desktop icons', `<p>Right-click the desktop > <b>Arrange Icons</b> > by Name, by Type, by Size or by Date. <b>Auto Arrange</b> keeps them tidy. <b>Line Up Icons</b> lines them up (they are always lined up, but it says so). Drag a box on the desktop to select several icons at once.</p>`, 'sort icons line up auto arrange');
  t('controlpanel', 'Control Panel', `<p>Start > Settings > Control Panel. Twenty-odd applets: Display (wallpaper, screen saver, colours), Mouse, Keyboard, Sounds, Date/Time, System (${L('devmgr', 'Device Manager')}), Modems, Network, Passwords, Power Management, Add/Remove Programs, Add New Hardware, Game Controllers, Regional Settings, Internet Options, Accessibility, Multimedia, Printers, Fonts and Gubbinz.</p>`, 'settings applets');
  t('explorer', 'JackOS Explorer and My Computer', `<p>My Computer shows the drives: A: (floppy, usually empty, sometimes Dave's), C: (Jack's PC, 6.4 GB), D: (the JACK ATTACK! cover disc), plus Control Panel, Printers, Dial-Up Networking and Scheduled Tasks. Double-click to go in. Right-click a file for Open, Send To, Delete, Rename and Properties. Some folders have passwords. Some files are hidden. View > Show hidden files.</p>`, 'files folders my computer drive');
  t('jacknet', 'JackNet Explorer (the browser)', `<p>JackNet Explorer 5 shows the JACK ATTACK! Online web site. Back, Forward, Stop, Refresh, Home, Search, Favorites, History, Mail, Print. Type things in the Address bar (some words go to secret pages). Help > Tip of the Day. View > Explorer Bar > History shows where you have been.</p>`, 'browser internet web');
  t('sfx', 'Sound effects are off', `<p>JackOS is silent until you turn sound effects on: click the speaker in the tray and untick Mute (or click the speaker once in older versions). Your browser needs a click before it will make any noise; that is a browser rule, not ours. Volume is on the slider. The ${L('themes', 'Desktop Themes')} have their own sound schemes.</p>`, 'no sound silent mute');

  // ---- Troubleshooting
  t('ts-slow', 'My computer is slow', `${STEPS(['Open ' + L('taskmgr', 'Task Manager') + ' (Ctrl+Shift+Esc) and look at the Performance tab. Is the CPU at 100%? Is a game running? Close the game.', 'Look at the ' + L('rsrcmtr', 'Resource Meter') + '. Under 30%? Close some jackos.', 'Run ' + R('defrag', 'Disk Defragmenter') + '. Watch the little blocks. This is the most satisfying thing a PC does.', 'Run ' + L('cleanmgr', 'Disk Cleanup') + '.', 'Still slow? It is a Pentium II 350. It is 1999. It is, honestly, really fast.'])}`, 'performance speed slow');
  t('ts-frozen', 'A program has stopped responding', `<p>Press <b>Ctrl+Alt+Del</b> once. Pick the program that says (not responding) and click End Task. Wait. Click End Task again when it asks. If the whole computer is frozen, press Ctrl+Alt+Del twice, and then it is really gone and you get the ${L('bsod', 'blue screen')}.</p>${NOTE('Gubbinz.exe always says (not responding). He is fine. He is eating.')}`, 'frozen hang crash not responding');
  t('bsod', 'The blue screen', `<p>Sometimes JackOS goes blue and says "A fatal exception 0E has occurred at 0028:C0011E36". This means it has crashed. Press any key to carry on, which restarts the computer. ScanDisk will run because it was not shut down properly.</p><p>It happens about once every eight hours of use, or whenever you press Ctrl+Alt+Del twice, or whenever Dave touches anything. It is not your fault. (Unless you ended KERNEL32.)</p>`, 'blue screen of death crash fatal exception');
  t('ts-lowmem', 'Low on virtual memory', `<p>"Your system is low on virtual memory" appears when you have loads of jackos open (about 11). JackOS pretends to make the swapfile bigger. Close some jackos. Or ask for more RAM: 32 MB is about \u00a330 and Christmas is coming.</p>`, 'memory swapfile paging warning');
  t('ts-printer', 'The printer isn\'t printing', `<p>Open the ${L('printing', 'JackJet 500')} window. Look at the little LCD on the printer:</p><ul><li><b>PAPER JAM</b>: click the scrunched page to pull it out. Retry.</li><li><b>ADD PAPER</b>: click the paper tray. Retry.</li><li>Something in capital letters you don't understand: press GO.</li><li><b>READY</b> but nothing happening: Printer > Pause Printing might be ticked. Untick it.</li></ul><p>If it is the Epson: it is out of cyan. It will always be out of cyan.</p>`, 'printer not working jam cyan');
  t('ts-modem', 'The Internet is slow or won\'t connect', `${STEPS(['Is anyone on the phone? Shout "I\'M ON THE INTERNET" down the stairs.', 'Is the modem plugged into the phone socket, and not the one in the wall that does nothing?', 'Open Phone Dialer and listen to the screechy noise. If it screeches, it is working.', '49,333 bps is the best it will ever do. 28.8 when it rains. The box says 56K. The box lies.'])}`, 'modem connection dial-up slow');
  t('ts-sound', 'There is no sound', `<p>Click the speaker in the tray. Untick Mute. Slide the volume up. Is the volume knob on the speaker turned up? Is the speaker plugged into the green hole, not the pink one? Is the SET BLASTER line in AUTOEXEC.BAT right (A220 I5 D1 H5 T6)? Yes. It is always right. Try again.</p>`, 'sound card mute speaker');
  t('ts-mouse', 'The mouse pointer jumps around', `<p>Turn the mouse over. Twist the ring. Take the ball out. Look at the three little rollers inside. They are covered in grey fluff. Pick it off with a fingernail. Put the ball back. Marvel at how smooth it is now. Repeat monthly.</p>`, 'mouse ball fluff jumpy');
  t('ts-gubbinz', 'Why is Gubbinz on my taskbar?', `<p>Gubbinz is the JackOS helper: a little green chap with big ears who pops up to help, whether you asked or not. ("It looks like you're writing a letter!") He installed himself. He is in the system tray (the egg is Jackotchi, his tiny mate), in the Control Panel, in Device Manager (the Gubbinz bus), in Task Manager (GUBBINZ.EXE, cannot be ended), in the Volume Control (his own slider, mute doesn't work) and in the Registry. He is not a virus. He is just very keen. Feed him.</p>`, 'helper pet gubbinz taskbar');
  t('ts-bin', 'How to defeat the Recycle Bin', `<p>You can't. Things you delete go in it. Things in it can be restored. Empty it and they are gone. There are old drawings and homework in there Jack cannot bring himself to lose. If you open the bin and restore them, Jack will be secretly pleased.</p><p>Deleting the Recycle Bin itself: no. Dragging the Recycle Bin into the Recycle Bin: no. Jack tried.</p>`, 'recycle bin delete restore');
  t('ts-scandisk', 'ScanDisk runs every time I start', `<p>Because the computer was not shut down properly. Someone switched it off at the wall. Someone always does. Use Start > Shut Down and wait for the orange screen. See ${L('shutdown', 'Shutting down properly')}.</p>`, 'scandisk startup boot');
  t('ts-y2k', 'Will my computer work in the year 2000?', `<p>Install the ${L('y2k', 'Y2K Compliance Patch')}. Run the Y2K Checker in C:\\Program Files. Keep a torch handy. Mom has beans. Dad says it is all nonsense. The news says the planes will fall out of the sky. Jack is going to Dave's for a party. We'll see.</p>`, 'y2k millennium 2000');
  t('ts-dave', 'Dave has broken something', `<p>Common Dave-related problems: switched off at the wall (${L('ts-scandisk', 'ScanDisk')}), the floppy with GLOOM on it is "lost" (it is in the drive), the mouse buttons are swapped (Control Panel > Mouse), the wallpaper is Hot Dog Stand (${L('themes', 'Desktop Themes')} > JackOS Standard), the joystick is calibrated for Dave's hands (Game Controllers), and the Registry has been "optimised" (restart and hope).</p>`, 'dave broke');

  // ---- The web site
  t('site', 'JACK ATTACK! Online', `<p>The web site that JackNet Explorer opens on. A games mag made by Jack: What's New, Games (demos you can play), Gubbinz (the shared pet), Screensaver, Reviews, Cheats, Hobby Corner, Letters, Art Wall, Chat, Forums and Members. The LIVE bits are shared with whoever else is looking at the site right now.</p>`, 'website homepage');
  t('site-games', 'The Games Arcade', `<p>Games you can play in the browser: JackTris, Blobbit Lob, Stickman Stunts, the Rubrick's cube and more. High scores are shared. Playing a game makes the CPU go to 100% in Task Manager, which is correct and realistic.</p>`, 'arcade demos play');
  t('site-chat', 'The chat room and WinPopup', `<p>Chat is on the web site (the little computers in the tray show how many people are about). <b>WinPopup</b> (Start > Programs > Accessories > Communications) sends a little message straight to another visitor's screen. Be nice.</p>`, 'chat message people online');
  t('site-cheats', 'The Cheats page', `<p>Type a cheat code in the box on the Cheats page. Classics work. The Konami one works anywhere, even on the desktop. Some cheats change the whole site. One makes everything rainbow. One gives the stickmen big heads.</p>`, 'cheat codes konami');
  t('secrets', 'Secrets', `<p>There are hundreds of secrets on this computer: hidden files, Run commands, address bar words, things in menus, things you have to click the wrong way. Finding one shows a gold star. Start > Find > <b>Secrets...</b> shows how many you've found and a vague hint for each one you haven't.</p><p>Nobody has found them all. Not even Jack. Jack hid them. Jack forgot where.</p>${TIP('The Search tab in this Help finds topics that are not in the Contents.')}`, 'easter eggs hidden find');

  // ---- Reference
  t('ref-files', 'What is on the C: drive', `<p>C:\\JACKOS (JackOS itself; don't delete it), C:\\JACKOS\\SYSTEM (the drivers, including GROT.VXD), C:\\JACKOS\\Tasks (scheduled tasks), C:\\JACKOS\\UPDATES (downloaded patches), C:\\Program Files (programs), C:\\My Documents (Jack's stuff: diary, lists, stories, homework, My Pictures, My Music), C:\\GAMES (Dad's DOS games), C:\\JACKATAK (the web site).</p>`, 'folders directory drive');
  t('ref-ports', 'Ports, IRQs and addresses', `<table class="sys-kv"><tr><td>IRQ 0</td><td>System timer</td></tr><tr><td>IRQ 1</td><td>Keyboard</td></tr><tr><td>IRQ 3</td><td>COM2 (modem)</td></tr><tr><td>IRQ 4</td><td>COM1 (mouse)</td></tr><tr><td>IRQ 5</td><td>JackBlaster 16</td></tr><tr><td>IRQ 6</td><td>Floppy</td></tr><tr><td>IRQ 7</td><td>LPT1 (JackJet 500)</td></tr><tr><td>IRQ 8</td><td>Real-time clock</td></tr><tr><td>IRQ 9</td><td>PCI steering (shareable)</td></tr><tr><td>IRQ 10</td><td>USB</td></tr><tr><td>IRQ 11</td><td>Graphics</td></tr><tr><td>IRQ 12</td><td>PS/2 mouse port (and the Bug Detector, which is the problem)</td></tr><tr><td>IRQ 13</td><td>Maths coprocessor</td></tr><tr><td>IRQ 14/15</td><td>IDE</td></tr></table>`, 'irq list table');
  t('ref-codes', 'Device Manager error codes', `<table class="sys-kv"><tr><td>Code 10</td><td>This device cannot start. (Hyperdrive Motivator.)</td></tr><tr><td>Code 12</td><td>Not enough free resources / IRQ conflict. (The detector in Other devices.)</td></tr><tr><td>Code 22</td><td>This device is disabled. (By Mom.)</td></tr><tr><td>Code 28</td><td>The drivers are not installed. (The Unknown Device. Nobody knows what it is.)</td></tr><tr><td>Code 31</td><td>Cannot load the drivers. (Y2K chip, driver dated 2000.)</td></tr><tr><td>Code 99</td><td>Dave.</td></tr></table>`, 'error codes device');
  t('ref-glossary', 'Glossary', `<dl class="sys-h-gl"><dt>Bps</dt><dd>Bits per second. The modem does 49,333 of them. The box says 56,000.</dd><dt>CMOS</dt><dd>The chip that remembers the date. Powered by a coin. The coin is winning.</dd><dt>Defrag</dt><dd>Putting the files back in order. Watch the blocks.</dd><dt>Floppy</dt><dd>1.44 MB. Not floppy. The old ones were floppy.</dd><dt>Gubbinz</dt><dd>The little green JackOS helper. Big ears. Always hungry.</dd><dt>IRQ</dt><dd>See ${L('irq', 'Fixing an IRQ conflict')}.</dd><dt>K</dt><dd>1,024 bytes. Or 1,000. Depends who is selling the hard disk.</dd><dt>Modem</dt><dd>The screechy box.</dd><dt>Plug and Play</dt><dd>Plug and Pray.</dd><dt>Pixel</dt><dd>One dot on the screen. There are 480,000 of them at 800 x 600.</dd><dt>WAAAGH</dt><dd>What Gorks shout. Also a Run command. Also what Dave says when he loses.</dd><dt>Y2K</dt><dd>See ${L('y2k', 'The Millennium Bug')}.</dd></dl>`, 'glossary words meaning');
  t('ref-credits', 'Credits', `<p>JackOS 98 Help was written by Jack, at the weekend, instead of doing homework (0 bytes). Spelling checked by Mom. Jokes checked by Dave (he said "they're alright"). Hardware section checked against the box the PC came in. Gubbinz contributed nothing and ate the first draft.</p>`, 'credits who made');

  // ---- extra funny-but-plausible (bulk)
  const EXTRA = [
    ['h-wallpaper', 'Changing the wallpaper', 'Right-click the desktop > Properties > Background, or use Desktop Themes. Paint can save a picture as wallpaper too (File > Set As Wallpaper). Tiled or centred. Stretched if you must.'],
    ['h-saver', 'Screen savers', 'Control Panel > Display > Screen Saver. Flying Saucers, Starfield, 3D Pipes, Mystify, 3D Text, Marquee, Curves and Colors, Digital Rain. It starts after a few minutes of nobody using the computer. Press Esc to stop it. Start > Run > saver starts it now.'],
    ['h-fonts', 'Fonts', 'Control Panel > Fonts, or Run > fonts. Double-click a font to see it big at every size with the quick brown fox. Print prints it on the JackJet.'],
    ['h-charmap', 'Character Map', 'For typing letters that aren\'t on the keyboard: accents, symbols, the copyright sign, the little wavy line. Start > Programs > Accessories > System Tools > Character Map. Spell something rude and Gubbinz will notice.'],
    ['h-regedit', 'The Registry', 'Regedit shows the Registry, which is where JackOS keeps all its settings. Dad says DO NOT TOUCH THE REGISTRY. Dad is right. Look, don\'t touch. HKEY_LOCAL_MACHINE\\SOFTWARE\\JackOS has some interesting keys in it though.'],
    ['h-notepad', 'Notepad', 'Writes text. Saves to My Documents (this session). Edit > Word Wrap. Edit > Time/Date puts the time in. It can\'t do bold. WordPad can do bold; nobody uses WordPad.'],
    ['h-paint', 'Paint', 'Draws pictures. Pencil, brush, spray can, fill, text, the shapes. 28 colours. Save as a .bmp in My Pictures. File > Set As Wallpaper puts it on the desktop. Jack\'s pixel spaceships were all done in Paint, with a mouse, and it took ages.'],
    ['h-calc', 'Calculator', 'View > Scientific for the big one. Try 4195835 / 3145727 for a bit of history. MC MR MS M+ are the memory. Nobody has ever used MS on purpose.'],
    ['h-jackamp', 'JackAmp', 'Plays MIDI tunes Jack wrote. Spectrum analyser, playlist, EQ (for show), volume slider (wired to the real volume). Double-click a song in the playlist. Skins: there is one skin.'],
    ['h-solitaire', 'Solitaire and FreeCell', 'Start > Programs > Games. Solitaire: Draw One or Draw Three, Vegas scoring if you are brave. Win and the cards bounce. FreeCell: game numbers like the real thing; #11982 is famously impossible, try it. Both count as "research".'],
    ['h-defrag', 'Disk Defragmenter', 'Start > Programs > Accessories > System Tools > Disk Defragmenter. Click Show Details and watch the little coloured blocks move around for twenty minutes. Do not touch anything or it starts again. Possibly the best thing about owning a computer.'],
    ['h-scandisk', 'ScanDisk', 'Checks the disk for errors. Standard or Thorough (the surface scan; go and have your tea). Finds lost clusters and makes them into FILE0001.CHK. One of the lost clusters is half a drawing of an X-wing.'],
    ['h-msinfo', 'System Information', 'Start > Run > msinfo32. Everything about the hardware and software, in a tree. Hardware Resources > IRQs, Components > Display, Software Environment > Running Tasks. Tools > Dr. Watson, System File Checker, Registry Checker.'],
    ['h-drwatson', 'Dr. Watson', 'Watches for crashes and writes a log about them. Start > Run > drwatson. He has a stethoscope icon. He has seen things.'],
    ['h-sfc', 'System File Checker', 'Checks that the JackOS files are the right JackOS files. Start > Run > sfc. It found GROT.VXD chewed once. It was fine.'],
    ['h-msconfig', 'System Configuration Utility', 'Start > Run > msconfig. Shows CONFIG.SYS, AUTOEXEC.BAT, SYSTEM.INI, JACKOS.INI and the Startup list. Untick things at your peril. "FREE Toolbar Helper" can be unticked. Please untick it.'],
    ['h-clipboard', 'The Clipboard', 'Copy puts things on the Clipboard. Paste takes them off. Clipboard Viewer (Start > Run > clipbrd) shows what is on it right now. One thing at a time. That is all the Clipboard can hold. One thing.'],
    ['h-briefcase', 'My Briefcase', 'For taking files to another computer on a floppy and keeping them in sync. Jack has never taken a file to another computer. The Briefcase has a sandwich in it.'],
    ['h-nethood', 'Network Neighborhood', 'Shows the other computers on JackNet: everyone on the site right now, Dave\'s PC, and GUBBINZ. Double-click one to see its shared folders. Send Message sends a WinPopup.'],
    ['h-dialup', 'Dial-Up Networking', 'My Computer > Dial-Up Networking > JackNet 56K. User name: thefamily. Double-click to dial. Listen for the screech. "Connected at 49,333 bps". Make New Connection asks for a phone number; there is only one Internet.'],
    ['h-phone', 'Phone Dialer', 'Dials a number through the modem so you can pick up the handset and talk. Speed dial 1 is Dave. Speed dial 2 is JackNet. Speed dial 3 is Grandma, who doesn\'t like being dialled by a computer.'],
    ['h-outlook', 'JackMail Express', 'E-mail. Jack has 0 new messages. Jack always has 0 new messages. Write to Jack on the Letters page instead. The Inbox has some old ones from Dave, and one from "FREE PRIZE!!!" that the anti-virus caught.'],
    ['h-av', 'JackNet Anti-Virus 99', 'Scans for viruses. Knows about 14,203 of them, including Melissa (an e-mail one) and CIH (goes off on 26 April). Dad bought it the day after Melissa. It found a Gubbinz in a hat and let him stay.'],
    ['h-coverdisc', 'The cover disc (D:)', 'Put the JACK ATTACK! cover disc in and it autoruns: play the demos, install, browse. Everything on it is on the web site already. The disc has a fingerprint on it.'],
    ['h-floppy', 'Drive A: says "not ready"', 'There is no disk in it. Click Retry. Click Retry again. On the third go it turns out there was a disk in there all along. It is Dave\'s. It says DAVE\'S DISK on it in felt tip.'],
    ['h-passwords', 'Folders with passwords', 'Some folders on C: ask for a password. The passwords are hidden around the site and the PC. The riddle is in Jack\'s lists. Think like an Ork. What do Gorks spend?'],
    ['h-hidden', 'Hidden files', 'Some files are hidden. In JackOS Explorer, View > Folder Options > Show all files. Then look in C:\\JACKOS. Then look in C:\\My Documents\\Diary. Then pretend you didn\'t.'],
    ['h-gubbinz-cpl', 'The Gubbinz Control Panel', 'Control Panel > Gubbinz. Feed, mood, how often he appears, whether he is allowed near the Recycle Bin (no). He installed this applet himself and it cannot be removed. Add/Remove Programs has tried.'],
    ['h-power', 'Power Management', 'Control Panel > Power Management. Stand by after 20 minutes: the screen goes dark. Wiggle the mouse. "Turn off hard disks" makes a clunk when it wakes up. Mom turns it off at the wall anyway.'],
    ['h-datetime', 'Setting the date and time', 'Control Panel > Date/Time, or double-click the clock. The year will not go past 1999. If you set it to 2000, JackOS explains why not. If you set the date to another day, the CMOS battery (a little coin) sets it straight back.'],
    ['h-regional', 'Regional Settings', 'English (United Kingdom). Pounds. dd/mm/yy. 24-hour clock. Metric. Do not change it to English (United States) or the dates go backwards and the "colour" spelling breaks.'],
    ['h-multimedia', 'Multimedia settings', 'Control Panel > Multimedia: the JackBlaster 16, 44.1 kHz, 16-bit; MIDI through the FM synth or the JackAmp Chiptune Engine; CD Audio volume (the little cable inside the case that goes from the CD-ROM to the sound card).'],
    ['h-joystick', 'Joysticks and gamepads', 'Control Panel > Game Controllers. Calibrate: move the stick in a circle and press a button. Dave\'s gamepad is borrowed and "not connected". The joystick port is on the sound card, next to the headphone hole.'],
    ['h-modemcpl', 'Modem settings', 'Control Panel > Modems: JackNet 56K Voice Modem on COM2. Properties > Maximum speed: 115200 (the modem laughs). Diagnostics > More Info talks to the modem in AT commands. ATDT is dial. ATH is hang up. ATZ is "please stop".'],
    ['h-network', 'Network settings', 'Control Panel > Network: Client for JackNet Networks, Dial-Up Adapter, TCP/IP. Identification: JACKS-PC in workgroup JACKNET. File and printer sharing is on so Dave can see the secret folder (he can\'t, it has a password).'],
    ['h-addhardware', 'Add New Hardware wizard', 'Control Panel > Add New Hardware. JackOS searches for Plug and Play devices, finds the same ones, and offers to install them again. If you have a card that is not Plug and Play, you pick it from a list of 4,000 things. The JackJet was easy; it was in the list.'],
    ['h-addremove', 'Add/Remove Programs', 'Control Panel > Add/Remove Programs. Uninstall things: DaveZip (day 412 of a 30-day trial), the FREE Smileys toolbar (please), Encyclopaedia of Everything (disc 4 missing). Gubbinz Virtual Pet cannot be removed. The uninstaller gets bitten.'],
    ['h-passwordcpl', 'Passwords and user profiles', 'Control Panel > Passwords. Change the JackOS password (there isn\'t one; press Enter at the log-on). User Profiles: everyone uses the same desktop. Mom\'s profile is "the same but with the sound off".'],
    ['h-internetopts', 'Internet Options', 'Control Panel > Internet Options, or JackNet Explorer Tools > Internet Options. Home page, History (20 days), Temporary Internet Files (delete them with Disk Cleanup), Security zones, Content Advisor (Mom set it to "no rude words", which is why the forum stars things out).'],
    ['h-bootseq', 'What happens when the PC starts', 'Power button. JackBIOS counts the memory (65536K OK). Detects the hard disk and the CD-ROM. "Press DEL to enter SETUP" (don\'t). ScanDisk if it was switched off at the wall. The JackOS 98 splash with the clouds. Dial JackNet. The Welcome screen (first time), then Tip of the Day, then you.'],
    ['h-bios', 'The BIOS setup', 'Press DEL while the memory is counting. You get a blue screen with yellow writing. Boot order, the clock, the hard disk type (Auto), the Turbo setting (does nothing). Dad changed something in here once and the PC didn\'t start for a day. Leave it.'],
    ['h-safe', 'Safe Mode', 'Hold F8 while starting and pick Safe Mode: 640 x 480, 16 colours, no sound, no modem, no Gubbinz, "Safe Mode" in all four corners. Use it when a driver has broken everything. Everything looks horrible. It is meant to.'],
    ['h-standby', 'Stand by', 'Start > Shut Down > Stand by. The screen goes black. The hard disk stops. Wiggle the mouse or press a key to come back. Sometimes it doesn\'t come back and you have to hold the power button. That is why nobody uses Stand by.'],
    ['h-ctrlaltdel', 'Ctrl+Alt+Del', 'The three-finger salute. Once: Close Program, a list of what is running; End Task on the stuck one. Twice: restart (everything unsaved is gone). It is on the keyboard for a reason. It is the first thing Dad tries.'],
    ['h-stickmen', 'Stickman Stunts', 'In the Games Arcade. Drag stickmen about, drop them off things. Physics. The BIGHEAD cheat makes their heads big, for no reason, like in that 007 game.'],
    ['h-jacktris', 'JackTris', 'Jack\'s own Blockology, from scratch. Arrows to move, up to turn, down to drop. The music is the old Russian folk song (it is public domain, Jack checked). The Desktop Theme called Blockology is based on it.'],
    ['h-cube', 'The Rubrick\'s cube', 'One cube shared by everyone on the site. Drag to turn faces. If someone else is turning it, you will see. It has been solved 3 times. Jack\'s best is 2:48 with a real one; see Cube Timer 2.0 in Accessories.'],
    ['h-grot', 'Gubbinz on the web site', 'The Gubbinz page has the shared pet. Poke him, feed him, everyone sees. The WAAAGH button only goes off if enough people press it at once. The Jackotchi in the tray is a different, smaller pet, who is just yours.'],
    ['h-artwall', 'The Art Wall', 'Draw a pixel on the shared wall. Everyone\'s pixels. It started as a spaceship. It is now mostly a spaceship with a moustache.'],
    ['h-forums', 'The forums', 'Boards for games, hobbies, cubes and "other". Members can post. Guests can read. [b]bold[/b] works. Be nice or the moderator (Jack) deletes it, and he is at school until half three.'],
    ['h-members', 'Logging on to JackNet', 'When JackOS starts, the Welcome to JackNet box asks for your user name and password (it remembers you next time). New? Type a new name and a password and you are signed up. Or Log on as Guest. Start > Log Off lets you switch. Members get a colour, a profile page and can post on the forums and the shout-outs. Guests are "Guest" plus a number. '],
    ['h-profile', 'My Profile', 'On the JACK ATTACK! website (www.jackattack.jnet), click My Profile in the member bar at the top of any page. Your nickname, your colour, how long you\'ve been a member, your high scores, your shout-outs. Other people can see it on the Members page.'],
    ['h-history', 'History and Favorites', 'JackNet Explorer remembers where you have been (View > Explorer Bar > History) and what you liked (Favorites > Add). Favorites appear on the Links bar. Organize Favorites lets you make folders you will never use.'],
    ['h-source', 'View Source', 'View > Source shows the HTML of the page. It is real. Jack typed it. There are comments in it. Some of the comments are secrets.'],
    ['h-addressbar', 'Typing in the Address bar', 'Type a section name (cheats, reviews, chat) or a word. Some words go to pages that are not on the menu. Jack will not say which. Try words you would try. Try www.jackattack.jnet/ followed by a thing.'],
    ['h-offline', 'Working offline', 'File > Work Offline in JackNet Explorer. You can still see the site, but nobody can see you and the LIVE bits stop. Good for reading the reviews without Dave popping up.'],
    ['h-print-web', 'Printing a web page', 'File > Print, or the Print button, sends the page to the JackJet 500. The queue window opens. It prints "JACK ATTACK!" at the top and lines for the rest, because the real page is 40 pages and the tray holds 10.'],
    ['h-tipoftheday2', 'Tips Jack actually uses', 'Shift+right-click for the real browser menu. Esc stops the screensaver. Hold the mouse over the clock. Right-click the taskbar. Ctrl+Shift+Esc. Type "help" in Run. Double-click the speaker. Press F1 in any window.'],
    ['h-beans', 'Mom\'s Y2K preparations', '40 tins of beans. 12 litres of water. 3 torches. A wind-up radio. A paper map. A tin opener (important). Candles. Mom says "better safe than sorry". Dad says "it\'s a computer problem, not a beans problem". Jack is going to Dave\'s.'],
    ['h-davedisk', 'Dave\'s floppy disk', 'It has GLOOM on it (4 disks, actually, but this is disk 2). It says DAVE\'S DISK in felt tip. It is always in drive A:. Dave wants it back. Dave has not asked for it back. It is the family\'s only spare floppy. Backup wants 1,440 of them.'],
    ['h-orkpage', 'Hobby Corner', 'Jack\'s hobby page: painting miniatures (Gorks, Space Marines, Eldar), AirMix kits, BLOCKO and K\'Nex. There is a bits box. The red ones go faster (this is a known fact). There are pictures, drawn in Paint, and a list of what\'s in the bits box. Do not ask about points or armies; Jack likes painting, not fighting.'],
    ['h-reviews', 'The reviews', 'Games Jack has played, out of 10. They appear on the site on the day they came out in 1999, so the list grows through the year. December is busy. The scores are honest. Dave disagrees with all of them.'],
    ['h-letters', 'Writing to Jack', 'Letters page. Type a letter. Jack reads them. Some get printed in the next issue. Jack\'s e-mail is not on the site because Mom said so. The Mail button on the Quick Launch bar goes to the Letters page.'],
    ['h-livebits', 'The LIVE bits', 'Anything with a red LIVE badge is shared with everyone on the site right now: the big red button, the visitor counter, the cube, Gubbinz, the chat, the Art Wall, the Desktop News Network ticker, and the people count in the tray.'],
    ['h-channel-onn', 'Desktop News Network', 'A channel on the Channel Bar. Breaking news, updated by whoever sends a headline in. Send one and it appears on everyone\'s Active Desktop ticker. Keep it family friendly; there is a filter and Mom.'],
    ['h-channel-weather', 'WeatherWatch 2000', 'Tomorrow: drizzle. Chance of drizzle: 90%. Outlook: grey. It has been like this since Jack set the channel up. (It is Britain.) The forecast is generated from the real date so at least the day name is right.'],
    ['h-channel-dave', 'Dave TV', 'Dave\'s channel. 24 hours of Dave. Currently showing: Dave losing at Goldenballs, Dave switching the PC off at the wall, Dave claiming the joystick is broken. Subscribers: 1 (Dave).'],
    ['h-galaxy-news', 'Galaxy Far Away News', 'A channel for the big space film that came out this summer (16 July in the UK). Jack has seen it twice. Dave has seen it three times and won\'t shut up about it. The channel reports on the queue outside the cinema, the toys, and whether the hyperdrive in Device Manager will ever work (no).'],
    ['h-theme-orks', 'Theme: Gorks!', 'Green and red. Camo wallpaper with Ork glyphs. The cursor is a choppa. The sounds are grunts and WAAAGHs. The Recycle Bin icon becomes a squig. One of Jack\'s favourites, obviously.'],
    ['h-theme-space', 'Theme: Outer Space', 'A starfield with a planet. Navy and purple jackos. Bleeps for the sounds. The cursor has a little rocket. Very calm. Dad likes this one.'],
    ['h-theme-tetris', 'Theme: Blockology', 'Falling blocks for wallpaper (in the seven proper colours). The window title bars are block coloured. The sounds are the line-clear bleeps. The cursor is an L piece. Lines appear on the desktop every so often. They do not clear.'],
    ['h-theme-cube', 'Theme: Cube Mania', 'A wallpaper of cube stickers in the six colours. Red/white/blue jackos. The cursor is a tiny cube. Sounds: clicky turns. Solved: never.'],
    ['h-theme-haunted', 'Theme: Haunted House', 'Purple fog, a house on a hill, bats. Dark grey jackos with a purple title bar. The cursor is a pointing skeleton hand. Sounds: creaks and a "wooo". The clock occasionally strikes thirteen (not really).'],
    ['h-theme-dinos', 'Theme: Dinosaurs', 'Jungle green with footprints. Earthy brown jackos. The cursor is a claw. Sounds: roars (synthesised, Jack did them in Sound Recorder). The wallpaper has a tiny dinosaur on it that is hard to find. It is a secret.'],
    ['h-theme-galaxy', 'Theme: Galaxy Far Away', 'The space-opera one. A deep starfield that slowly drifts, a glowing-blade cursor (blue; right-click is red, for the baddies), black and gold jackos, and a sound scheme of hums, blasters and a very big door. No film music, no film pictures; original, like the rest of this PC. Jack says "it\'s not a copy, it\'s a tribute".'],
    ['h-theme-sea', 'Theme: Under the Sea', 'Deep blue with bubbles and a fish that swims past. Aqua jackos. Cursor: a little fish. Sounds: blub. Gubbinz is scared of it.'],
    ['h-theme-millennium', 'Theme: Millennium', 'Fireworks on midnight blue, gold jackos, a countdown feel. The cursor is a sparkler. The sounds are party poppers. For 31 December. Which never comes. Which is why it is a theme.'],
    ['h-theme-matrix', 'Theme: The Modemtrix', 'Green letters falling down a black screen. Black jackos with green title bars. Cursor: a white rabbit. Sounds: dial tones. Jack saw this film in June and it changed his wallpaper forever (until the next film).'],
    ['h-theme-hotdog', 'Theme: Hot Dog Stand', 'Red and yellow. All of it. Every window. It is included because it is traditional. It is a secret if you apply it. It is a mistake if you leave it on.'],
    ['h-themes-restore', 'Putting the theme back to normal', 'Desktop Themes > pick "JackOS Standard" > Apply. Or Control Panel > Display > Appearance > JackOS Standard. Or Run > themes. If the cursor is still a glowing blade, untick "Mouse pointers" and Apply again.'],
    ['h-tray-printer', 'The printer icon in the tray', 'Appears when the JackJet is printing. Double-click to open the queue. It goes red when the printer has jammed or run out of paper. It disappears when the queue is empty, after a polite pause.'],
    ['h-newhardware', '"New Hardware Found"', 'Every so often JackOS spots something new plugged in (it isn\'t) and installs it: the same monitor again, a crisp crumb in the USB port, the printer forgetting it was installed, a Hyperdrive Motivator. Click the balloon to see it in Device Manager. Start > Run > newhardware makes it happen now.'],
    ['h-lowvm', '"Your system is low on virtual memory"', 'Open 11 windows and JackOS panics. It increases the swapfile (it says). Close some windows. The swapfile is C:\\JACKOS\\WIN386.SWP and it is 112 MB, which is bigger than the first hard disk Dad ever had.'],
    ['h-show-desktop', 'Show Desktop', 'The little desk icon on the Quick Launch bar, next to the Start button. Click it: every window minimises and you can see the wallpaper. Click it again: they all come back. Start > Run > cls does the same.'],
    ['h-cascade', 'Cascade and Tile', 'Right-click the taskbar. Cascade stacks the jackos like a fanned deck of cards. Tile Horizontally / Vertically squashes them all onto the screen at once, which is useful for comparing two things and useless for everything else.'],
    ['h-marquee', 'Selecting several icons at once', 'Press on an empty bit of the desktop and drag. A dotted box appears. Everything inside it is selected. Lasso five or more and JackOS is impressed.'],
    ['h-rename', 'Renaming things', 'Click an icon on the desktop, press F2 (or right-click > Rename), type, press Enter. Esc cancels. You cannot use \\ / : * ? " < > | in a name, because DOS. Name a folder after Gorks and see what happens.'],
    ['h-sendto', 'Send To', 'Right-click a file > Send To > 3\u00bd Floppy (A:) or My Briefcase. The floppy is full. It has GLOOM on it. The Briefcase has a sandwich in it.'],
    ['h-properties', 'Properties', 'Right-click anything > Properties. Files: size, dates, attributes. Drives: the pie chart of used/free, and the Disk Cleanup button. The desktop: Display Properties. The taskbar: Taskbar Properties. Printers: Paper and Graphics. Devices: Driver and Resources. Everything has Properties. Properties is the best menu.'],
    ['h-pcloadletter', 'The printer says something in capitals and stops', 'Press GO. See ' + '%MC%' + '. Every printer in 1999 does this. The JackJet\'s messages are: MC FEED A4, TRAY 1 HUNGRY, LOAD A4 PLAIN PRESS GO, ERR 50.2 RESTART, PAPER WAD AT C, HEAD PARK FAIL. The manual (112 pages, 40 of them in German) is in the loft.'],
    ['h-testpage', 'Printing a test page', 'JackJet 500 window > Print Test Page (or the Printers folder > right-click the JackJet > Properties > Print Test Page, or Run > printtest). It prints the JackOS flag and a table of the driver details. It is the only thing the printer prints reliably.'],
    ['h-purge', 'Cancelling printing', 'JackJet 500 window > Printer > Purge Print Documents. Or right-click a document in the queue > Cancel Printing. Or, if you are desperate, Task Manager > Processes > SPOOL32.EXE > End Process. The printer looks relieved.'],
    ['h-gubbinz-vol', 'Gubbinz has his own volume slider', 'Volume Control > Gubbinz. Slide it up and he gets louder. Tick Mute. He keeps making noise. The mute is for show. Everything about Gubbinz is for show, except the biting.'],
    ['h-record-reverse', 'Playing a recording backwards', 'Sound Recorder > Effects > Reverse. Record yourself saying something, reverse it, play it. Then say what you heard, record THAT, and reverse it again. Dave did this for an hour.'],
    ['h-sysmon-items', 'What the System Monitor items mean', 'Processor Usage: how busy the Pentium II is. Allocated memory: how much of the 64 MB is used. Swapfile in use: how much has spilled onto the hard disk (bad). Threads: little jobs. Reads/second: the disk going tk-tk-tk. Dial-Up Adapter bytes: the modem (5,600 a second is the dream). The Gubbinz one: self-explanatory.'],
    ['h-resources-why', 'What are "system resources"?', 'Two little 64 KB bits of memory (User and GDI) that every window, menu, button and icon takes a slice of. When they run out, nothing can open, no matter how much RAM you have. It is a JackOS 98 thing. It is why you can have 64 MB and still get "out of memory". Close jackos.'],
    ['h-millennium-job', 'The "Millennium" scheduled task', 'In Scheduled Tasks. Runs PARTY.EXE at 23:59 on 31/12/1999. Status: waiting. It will wait forever. Right-click > Run to try it early and see what JackOS says. It cannot be deleted. It is coming whether you like it or not. (It isn\'t.)'],
    ['h-register', 'Registering JackOS', 'Welcome screen > Register Now. The wizard asks your name (your nickname), what you use the computer for (games), and whether you want to hear about new products (no). It then dials JackNet, "sends" the form (it doesn\'t), and gives you a registration number. Nothing leaves your computer.'],
    ['h-icw', 'The Internet Connection Wizard', 'Welcome screen > Connect to the Internet, or Accessories > Communications. Three choices: sign up for a new account (there is only JackNet), set up an existing one (JackNet 56K, already done), or "I already have it" (correct). It dials to prove it.'],
    ['h-discover', 'The Discover JackOS 98 tour', 'Welcome screen > Discover JackOS 98. An animated tour: Computer Essentials, What\'s New, More JackOS, and a Secrets chapter that only unlocks when you have watched the others. Click the arrows. Finish the whole thing and you get a star.'],
    ['h-help-itself', 'Using this Help', 'Contents: books and pages, click to open. Index: type a word, pick from the list. Search: type anything, finds it in the text of every topic. Back goes back. Hide hides the left panel. Options > Print prints the topic on the JackJet. Web Help goes to the web site. Press F1 anywhere for this.'],
    ['h-helpsecret', 'Topics that are not in the Contents', 'There are a few. They only turn up if you Search for the right word. Adventure game players know a magic word that makes nothing happen. Try it in the Search box.'],
    ['h-orknames', 'Hobby words', 'Undercoat: the first coat, usually black. Drybrushing: wipe nearly all the paint off and flick it over the edges; it is basically magic. Bits box: where spare arms and heads live. Kitbash: glue two kits together and see what happens. Weathering: making a spaceship look like it has been somewhere. For the War Hamster fans: Boyz (the lads), Trukk (a lorry, painted red). Teef: teeth. Gorks are very proud of theirs.'],
    ['h-cube-notation', 'Cube notation', 'F R U B L D: front, right, up, back, left, down, clockwise. Add an apostrophe (R\') for anticlockwise, 2 (R2) for twice. Jack\'s favourite algorithm is R U R\' U\' because it is the first one everybody learns and it does basically everything.'],
    ['h-tetris-names', 'The seven Blockology pieces', 'I (the long one, the one you are always waiting for), O (the square), T, S, Z (the annoying ones), J and L. Four squares each. In JackTris they are the proper colours. There is a Desktop Theme with all seven on it.'],
    ['h-1999', 'Things that happened in 1999 (so far)', 'A big space film (July). A film with a red pill (June). Pocket Critters on the Game Lad (October). Daydream in October (Jack is saving). The Millennium Bug (December, allegedly). Jack\'s mag going online (that\'s this). Dave\'s voice breaking (ongoing).'],
    ['h-dreamcast', 'Daydream', 'Out in the UK on 14 October 1999. It has a modem built in. A MODEM. BUILT IN. Jack has \u00a3112 saved. It costs \u00a3199. The countdown is on the home page. Dad says "we\'ll see". Dad said "we\'ll see" about the Voodoo2 and look what happened.'],
    ['h-dial-sound', 'Why the modem makes that noise', 'Dial tone, the number (beeps), ringing, the other end picks up, then the two modems screech at each other to agree a speed. The screech is them negotiating. If the screech stops early, Mom picked up. The "boing boing" bit is the V.90 training. Jack can do an impression of all of it.'],
    ['h-56k', 'Why 56K is never 56K', 'The phone line, the exchange, the weather, the distance, the other modem, and physics. 53K is about the most a 56K modem ever gets anyway. 49,333 bps is a good day. Downloads: a 4 MB song takes 15 minutes. A 40 MB codec takes until 2003. A Y2K patch takes 4 hours at 28.8K with Mom picking up three times.'],
    ['h-cds', 'How much is a CD-ROM?', '650 MB. That is 451 floppies. A CD writer costs \u00a3250 and blank discs are \u00a31 each. Jack has worked out that backing up the PC to CDs would take 9 CDs and an afternoon, which is better than 3,600 floppies and 36 hours. Dad has not been told about this plan yet.'],
    ['h-megahertz', 'What does 350 MHz mean?', 'The processor does 350 million ticks a second. A 486 did 66 million. Next year\'s will do a thousand million (a "gigahertz"), which Dave says is impossible and Jack says is definitely happening. The Celeron 300A can be overclocked to 450 if you are brave and have a big fan. Dad is not brave.'],
    ['h-ram', 'What does 64 MB mean?', 'Sixty-four million bytes of memory. JackOS uses about 30 of them doing nothing. A game uses the rest. The swapfile on the hard disk pretends to be more. Another 64 MB stick is about \u00a360 (it was about \u00a3200 a couple of years ago). There are two slots free. Christmas list.'],
    ['h-voodoo', 'The 3dfx Voodoo2', 'The 3D card. 12 MB. It plugs into a PCI slot and a little cable goes from the normal graphics card into it and out to the monitor. When a 3D game starts the screen flickers and goes "thoong" and then everything is smooth and has fog. Jack\'s best birthday present. Second best: the ULTRA 64.'],
    ['h-crt', 'The monitor', '14 inch. 800 x 600 at 75 Hz (60 Hz flickers and gives you a headache). It weighs as much as Dave. It hums. When you turn it off the picture shrinks to a line and then a dot, which is the best bit. Degauss makes it go "bwong" and wobble. Do not press Degauss more than once a day; it enjoys it too much.'],
    ['h-pattern', 'Why is the hard disk only 5.98 GB?', 'It says 6.4 GB on the box. Because the box people count 1,000 bytes as a K and the computer counts 1,024. Nobody is lying. Everybody is annoyed. Also FAT32 takes a bit. Also there is 1.21 GB free and most of the rest is games.'],
  ];
  EXTRA.forEach(([id, title, text]) => t(id, title, `<p>${text.replace('%MC%', L('mcfeed', 'What does MC FEED A4 mean?'))}</p>`));
  // hidden topics (Search only)
  t('xyzzy', 'Xyzzy', `<p>Nothing happens.</p><p>...</p><p>Actually, something happens: you found a hidden Help topic. In the old text adventures, XYZZY was a magic word that teleported you. Here it just gives you a star. Try typing it in Start > Run as well.</p>`, 'magic word adventure plugh');
  t('h-secret-bits', 'Where Jack hid some of the secrets', `<p>This topic is not in the Contents. You searched for it, so you deserve a hint. There are secrets in: the Run box (dozens of words), the address bar (dozens more), Device Manager (fix the IRQ, poke the hyperdrive), Task Manager (try to end things), the printer (jam, paper), Sound Recorder (reverse), Backup (disk 3), Disk Cleanup (finish it), Desktop Themes (all of them), the Channel Bar (subscribe, send a headline), the desktop (New Folder named after Gorks; lasso five icons), the Welcome tour (to the end), Tip of the Day (15 of them), the Volume Control (max, and Gubbinz), and this Help (read 20 topics; find xyzzy).</p>`, 'secret hint list cheat where');
  t('h-mom', 'Mom', `<p>Mom runs the house, the beans and the phone line. Mom disabled the toaster. Mom turns the PC off at the wall ("it's humming"). Mom set the Content Advisor. Mom will not let Jack's e-mail go on the Internet. Mom is, Jack admits, usually right. Spelt "Mom", not the other way, because that is how Jack spells it and he is not changing it for anyone.</p>`, 'mum mother');

  // ---- contents tree: [book, [topic ids]]
  const BOOKS = [
    ['Welcome', ['welcome', 'whatsnew', 'sysreq', 'about-this-pc', 'h-1999', 'ref-credits']],
    ['Using JackOS 98', ['desktop', 'startmenu', 'windows', 'taskbar', 'tray', 'clock', 'mouse', 'keyboard', 'touch', 'runcmds', 'shutdown', 'msdos', 'h-standby', 'h-safe', 'h-bootseq', 'h-bios', 'h-ctrlaltdel', 'h-show-desktop', 'h-cascade', 'h-marquee', 'h-rename', 'h-sendto', 'h-properties']],
    ['The desktop', ['newfolder', 'arrange', 'activedesk', 'channels', 'h-channel-onn', 'h-channel-weather', 'h-channel-dave', 'h-galaxy-news', 'h-wallpaper', 'h-saver', 'welcome-tour', 'h-discover', 'h-register', 'h-icw', 'tips']],
    ['Desktop Themes', ['themes', 'h-theme-orks', 'h-theme-space', 'h-theme-tetris', 'h-theme-cube', 'h-theme-haunted', 'h-theme-dinos', 'h-theme-galaxy', 'h-theme-sea', 'h-theme-millennium', 'h-theme-matrix', 'h-theme-hotdog', 'h-themes-restore']],
    ['System Tools', ['taskmgr', 'devmgr', 'irq', 'hyperdrive', 'sysmon', 'h-sysmon-items', 'rsrcmtr', 'h-resources-why', 'sched', 'h-millennium-job', 'backup', 'cleanmgr', 'tuneup', 'h-defrag', 'h-scandisk', 'h-msinfo', 'h-drwatson', 'h-sfc', 'h-msconfig', 'h-regedit', 'update', 'y2k', 'h-newhardware', 'h-lowvm']],
    ['Printing', ['printing', 'printers-folder', 'mcfeed', 'h-pcloadletter', 'h-testpage', 'h-purge', 'h-tray-printer', 'h-print-web', 'ts-printer']],
    ['Sound and multimedia', ['volume', 'sfx', 'sndrec', 'h-record-reverse', 'h-gubbinz-vol', 'h-jackamp', 'h-multimedia', 'h-joystick', 'h-dial-sound']],
    ['Accessories', ['accwiz', 'h-notepad', 'h-paint', 'h-calc', 'h-charmap', 'h-clipboard', 'h-fonts', 'h-briefcase', 'h-phone', 'h-outlook', 'h-av', 'h-solitaire', 'h-jacktris', 'h-cube', 'h-cube-notation', 'h-tetris-names']],
    ['Control Panel', ['controlpanel', 'h-datetime', 'h-regional', 'h-power', 'h-passwordcpl', 'h-internetopts', 'h-modemcpl', 'h-network', 'h-addhardware', 'h-addremove', 'h-gubbinz-cpl']],
    ['Files, drives and the network', ['explorer', 'ref-files', 'h-hidden', 'h-passwords', 'h-floppy', 'h-davedisk', 'h-coverdisc', 'h-cds', 'h-pattern', 'h-nethood', 'h-dialup', 'h-56k', 'h-offline']],
    ['JackNet Explorer and the web site', ['jacknet', 'site', 'site-games', 'h-stickmen', 'h-grot', 'h-artwall', 'site-chat', 'h-forums', 'h-members', 'h-profile', 'site-cheats', 'h-reviews', 'h-letters', 'h-livebits', 'h-history', 'h-source', 'h-addressbar', 'h-dreamcast', 'h-orkpage', 'h-orknames']],
    ['Troubleshooting', ['ts-slow', 'ts-frozen', 'bsod', 'ts-lowmem', 'ts-modem', 'ts-sound', 'ts-mouse', 'ts-scandisk', 'ts-y2k', 'ts-gubbinz', 'ts-bin', 'ts-dave', 'h-beans']],
    ['Reference', ['ref-ports', 'ref-codes', 'ref-glossary', 'h-megahertz', 'h-ram', 'h-voodoo', 'h-crt', 'secrets', 'h-help-itself', 'h-helpsecret', 'h-tipoftheday2']],
  ];
  const BOOKED = new Set(BOOKS.flatMap(b => b[1]));
  const byId = {}; T.forEach(x => { byId[x.id] = x; });
  // alias ids the rest of the pack jumps to
  const ALIAS = { printing: 'printing', taskmgr: 'taskmgr', devmgr: 'devmgr', irq: 'irq', sysmon: 'sysmon', sched: 'sched', sndrec: 'sndrec', volume: 'volume', themes: 'themes', channels: 'channels', welcome: 'welcome' };
  const BOOK_ICO = o => `<svg viewBox="0 0 16 16" width="16" height="16"><path d="M2 3h5l1 1h6v9H2z" fill="${o ? '#f2d16b' : '#e8c050'}" stroke="#7a5a00"/>${o ? '<path d="M2 6h12" stroke="#7a5a00"/>' : ''}</svg>`;
  const PAGE_ICO = '<svg viewBox="0 0 16 16" width="16" height="16"><path d="M3 1h7l3 3v11H3z" fill="#fff" stroke="#000"/><text x="8" y="12" text-anchor="middle" font-family="Arial" font-weight="bold" font-size="9" fill="#000080">?</text></svg>';
  // the official JackOS 98 help icons (closed book, open book, topic page) when icons.js is loaded
  const BOOK_J = o => window.JICON ? JICON.get(o ? 'bookOpen' : 'helpbook', 16) : BOOK_ICO(o), PAGE_J = () => window.JICON ? JICON.get('helptopic', 16) : PAGE_ICO;

  X.P['system.help'] = arg => {
    const b = h(`<div class="sys-h-tb"><button type="button" class="btn" data-h="hide"><i>\u25c4</i>Hide</button><button type="button" class="btn" data-h="back" disabled><i>\u2190</i>Back</button><button type="button" class="btn" data-h="fwd" disabled><i>\u2192</i>Forward</button><button type="button" class="btn" data-h="opt"><i>\u2630</i>Options</button><button type="button" class="btn" data-h="web"><i>\u25cf</i>Web Help</button></div>
      <div class="sys-h-main"><div class="sys-h-nav"><div class="sys-tabs"><button type="button" class="on" data-n="contents">Contents</button><button type="button" data-n="index">Index</button><button type="button" data-n="search">Search</button></div><div class="sys-h-pane"></div></div><div class="sys-h-doc"><div class="sys-h-hd"></div><div class="sys-h-body"></div></div></div>`, 'sys-help');
    const w = A.win('JackOS Help', b, { w: 720, h: 500, icon: I.help, status: true, minW: 320, minH: 300 });
    const pane = qs(b, '.sys-h-pane'), doc = qs(b, '.sys-h-body'), hd = qs(b, '.sys-h-hd'), nav = qs(b, '.sys-h-nav');
    const openBooks = new Set([0]); let cur = null, hist = [], fwd = [], read = get('helpread', []);
    const hidden = () => nav.classList.contains('hide');
    function show(id, noHist) {
      const x = byId[ALIAS[id] || id] || byId.welcome;
      if (cur && !noHist) { hist.push(cur); fwd = []; }
      cur = x.id;
      hd.innerHTML = `<h2>${esc(x.title)}</h2>`;
      doc.innerHTML = x.html.replace('%N%', String(T.length)) + `<div class="sys-h-foot">${!BOOKED.has(x.id) ? '<i>(This topic is not in the Contents. Well found.)</i>' : ''} Related: ${(BOOKS.find(bk => bk[1].includes(x.id)) || BOOKS[0])[1].filter(i => i !== x.id).slice(0, 4).map(i => L(i, byId[i].title)).join(' \u2022 ')}</div>`;
      doc.scrollTop = 0;
      qs(b, '[data-h=back]').disabled = !hist.length; qs(b, '[data-h=fwd]').disabled = !fwd.length;
      w.status.textContent = x.title;
      if (!read.includes(x.id)) { read.push(x.id); put('helpread', read); if (read.length >= 20) S('helpbook'); }
      if (x.id === 'xyzzy') S('xyzzy');
      if (!hidden()) { qsa(pane, '.sys-h-t').forEach(e => e.classList.toggle('sel', e.dataset.t === x.id)); }
      if (touch() && innerWidth < 700 && !hidden()) toggleNav(true);
    }
    on(doc, 'click', ev => { const a = ev.target.closest('a[data-t],a[data-run]'); if (!a) return; ev.preventDefault(); if (a.dataset.t) { if (!BOOKED.has(a.dataset.t)) {} show(a.dataset.t); } else A.run(a.dataset.run); });
    function contents() {
      pane.innerHTML = `<div class="sys-h-tree">${BOOKS.map((bk, i) => `<div class="sys-h-b" data-b="${i}">${BOOK_J(openBooks.has(i))}<span>${esc(bk[0])}</span></div>${openBooks.has(i) ? bk[1].map(id => `<div class="sys-h-t${cur === id ? ' sel' : ''}" data-t="${id}">${PAGE_J()}<span>${esc(byId[id].title)}</span></div>`).join('') : ''}`).join('')}</div>`;
      qsa(pane, '.sys-h-b').forEach(e => on(e, 'click', () => { const i = +e.dataset.b; if (openBooks.has(i)) openBooks.delete(i); else openBooks.add(i); contents(); }));
      qsa(pane, '.sys-h-t').forEach(e => on(e, 'click', () => show(e.dataset.t)));
    }
    function index() {
      const words = []; T.forEach(x => { if (!BOOKED.has(x.id)) return; words.push([x.title, x.id]); (x.kw || '').split(/\s+/).filter(k => k.length > 2).forEach(k => words.push([k.toLowerCase() + ' (' + x.title + ')', x.id])); });
      words.sort((a, b2) => a[0].localeCompare(b2[0], 'en', { sensitivity: 'base' }));
      pane.innerHTML = `<label class="sys-lbl">Type in the keyword to find:<input type="text" class="sys-h-q" autocomplete="off"></label><div class="field sys-h-list"></div><button type="button" class="btn sys-h-disp">Display</button>`;
      const inp = qs(pane, '.sys-h-q'), list = qs(pane, '.sys-h-list');
      const draw = () => { const q = inp.value.trim().toLowerCase(); const hits = words.filter(x => !q || x[0].toLowerCase().includes(q)); list.innerHTML = hits.slice(0, 300).map(x => `<div class="sys-h-i" data-t="${x[1]}">${esc(x[0])}</div>`).join('') || '<div class="sys-h-i">(nothing)</div>'; const f = qs(list, '.sys-h-i'); if (f) f.classList.add('sel'); qsa(list, '.sys-h-i').forEach(e => { on(e, 'click', () => { qsa(list, '.sys-h-i').forEach(x => x.classList.toggle('sel', x === e)); if (touch()) show(e.dataset.t); }); on(e, 'dblclick', () => show(e.dataset.t)); }); };
      on(inp, 'input', draw); on(inp, 'keydown', ev => { if (ev.key === 'Enter') { const s = qs(list, '.sel'); if (s) show(s.dataset.t); } });
      on(qs(pane, '.sys-h-disp'), 'click', () => { const s = qs(list, '.sel'); if (s && s.dataset.t) show(s.dataset.t); });
      draw(); if (!touch()) inp.focus();
    }
    function search() {
      pane.innerHTML = `<label class="sys-lbl">Type in the word(s) to search for:<input type="text" class="sys-h-q" autocomplete="off"></label><div class="row"><button type="button" class="btn sys-h-go">List Topics</button><button type="button" class="btn sys-h-disp">Display</button></div><div class="field sys-h-list"><div class="sys-h-i">Type a word and click List Topics.</div></div><div class="small sys-h-cnt"></div>`;
      const inp = qs(pane, '.sys-h-q'), list = qs(pane, '.sys-h-list');
      const strip = s => s.replace(/<[^>]+>/g, ' ').toLowerCase();
      const run = () => {
        const q = inp.value.trim().toLowerCase(); if (!q) return;
        const terms = q.split(/\s+/);
        const hits = T.map(x => { const txt = strip(x.title + ' ' + x.html + ' ' + x.kw); let sc = 0; terms.forEach(tm => { if (x.title.toLowerCase().includes(tm)) sc += 5; if (x.id === tm) sc += 20; const n = txt.split(tm).length - 1; sc += n; }); return [sc, x]; }).filter(r => r[0] > 0).sort((a, b2) => b2[0] - a[0]);
        list.innerHTML = hits.slice(0, 100).map(([sc, x]) => `<div class="sys-h-i" data-t="${x.id}">${esc(x.title)} <small>(${sc})</small></div>`).join('') || '<div class="sys-h-i">No topics found. Try a different word. Try "dave".</div>';
        qs(pane, '.sys-h-cnt').textContent = `${hits.length} topic(s) found`;
        qsa(list, '.sys-h-i[data-t]').forEach(e => { on(e, 'click', () => { qsa(list, '.sys-h-i').forEach(x => x.classList.toggle('sel', x === e)); if (touch()) show(e.dataset.t); }); on(e, 'dblclick', () => show(e.dataset.t)); });
        const f = qs(list, '.sys-h-i[data-t]'); if (f) f.classList.add('sel');
      };
      on(qs(pane, '.sys-h-go'), 'click', run); on(inp, 'keydown', ev => { if (ev.key === 'Enter') { run(); } });
      on(qs(pane, '.sys-h-disp'), 'click', () => { const s = qs(list, '.sel'); if (s && s.dataset.t) show(s.dataset.t); });
      if (!touch()) inp.focus();
    }
    const tabFns = { contents, index, search };
    qsa(b, '.sys-tabs button').forEach(bt => on(bt, 'click', () => { qsa(b, '.sys-tabs button').forEach(x => x.classList.toggle('on', x === bt)); tabFns[bt.dataset.n](); }));
    function toggleNav(force) { const hide = force == null ? !hidden() : force; nav.classList.toggle('hide', hide); qs(b, '[data-h=hide]').innerHTML = hide ? '<i>\u25ba</i>Show' : '<i>\u25c4</i>Hide'; if (!hide) contents(); }
    on(qs(b, '[data-h=hide]'), 'click', () => toggleNav());
    on(qs(b, '[data-h=back]'), 'click', () => { if (!hist.length) return; fwd.push(cur); show(hist.pop(), true); qs(b, '[data-h=fwd]').disabled = false; });
    on(qs(b, '[data-h=fwd]'), 'click', () => { if (!fwd.length) return; hist.push(cur); show(fwd.pop(), true); });
    on(qs(b, '[data-h=opt]'), 'click', ev => { const r = ev.currentTarget.getBoundingClientRect(); IE.menu([{ label: 'Home', act: () => show('welcome') }, { label: 'Stop', dis: true }, { label: 'Refresh', act: () => show(cur, true) }, '-', { label: 'Internet Options...', act: () => A.run('inetcpl.cpl') }, { label: 'Print...', act: () => X.Spooler.print('JackOS Help - ' + byId[cur].title + '.htm', { pages: 1, owner: 'Help', text: byId[cur].title + '\n\n' + byId[cur].html.replace(/<[^>]+>/g, '') }) }, '-', { label: 'Search Highlight Off', chk: true }, { label: 'Show Read Topics', act: () => msg('JackOS Help', `You have read ${read.length} of ${T.length} topics.${read.length >= 20 ? ' You are officially a bookworm.' : ' Keep going. 20 and you get a star.'}`, 'info') }], r.left, r.bottom); });
    on(qs(b, '[data-h=web]'), 'click', () => { S('helpweb'); document.getElementById('browser').classList.remove('min'); IE.navigate('http://support.jacknet'); toast('Web Help', 'Connecting to JackNet Online Support... (It is Jack. Jack is the support.)', 4000); });
    contents(); show(arg && typeof arg === 'string' ? arg : 'welcome', true);
    if (touch() && innerWidth < 700) toggleNav(true);
    return w;
  };
  X.HELP_COUNT = T.length;
})();
